INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百二十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e13dd68e0caa3222d6fb3adad85c0ad8d6bd39d8/content/books/zizhi-tongjian/vol-286/year-0947/part-09/sources/library/jiuwudaishi-125-zhao-hui/source.txt", "note": "《旧五代史》卷一百二十五，段落 jiu-wudaishi-205deb4a7860-p002912；EPUB电子本，纸本及异文待核", "id": "8e1c71bc-d2ba-5151-8cad-bfe34f701ef3"}, {"title": "宋史·巻二百六十一", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e13dd68e0caa3222d6fb3adad85c0ad8d6bd39d8/content/books/zizhi-tongjian/vol-286/year-0947/part-09/sources/library/songshi-261-li-wanchao/source.txt", "note": "《宋史》巻二百六十一，段落 songshi-9c6e46fee832-p058020；EPUB电子本，纸本及异文待核", "id": "c73dc5ed-1158-5779-960a-9067a0ce054f"}, {"title": "资治通鉴·后汉纪一", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c55e23db2fe30e33712619797f5300a286a58c03/content/books/zizhi-tongjian/vol-286/year-0947/part-08/sources/library/tongjian-286-947-li-wuyue/source.txt", "note": "《资治通鉴》后汉纪一，段落 zizhi-tongjian-a63549944a71-p003399；电子底本待考，分段待核", "id": "3b9e025c-ba6d-5964-9920-6d85a4f59344"}, {"title": "旧五代史·卷九十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/576d9a100a90791fb2103eff8dc0a2a9ed251986/content/books/zizhi-tongjian/vol-286/year-0947/part-07/sources/library/jiuwudaishi-099-imperial-title/source.txt", "note": "《旧五代史》卷九十九，段落 jiu-wudaishi-205deb4a7860-p002427；EPUB电子本，纸本及异文待核", "id": "ee32ab47-1d43-56d4-8578-da743dfdb40e"}, {"title": "新五代史·卷十", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/576d9a100a90791fb2103eff8dc0a2a9ed251986/content/books/zizhi-tongjian/vol-286/year-0947/part-07/sources/library/xinwudaishi-010-accession/source.txt", "note": "《新五代史》卷十，段落 xin-wudaishi-b08f244b9241-p000348；EPUB电子本，纸本及异文待核", "id": "f718016c-9527-5d8f-aa77-cf220d109f89"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "史弘肇", "aliases": ["史宏肇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "荥泽人，947年二月任刘知远的武节都指挥使，奉命在球场集合各军，宣布出兵日期。《旧五代史》亦有史宏肇的字形。生卒年暂未录入。", "biography": null, "status": "draft", "id": "c36d0d69-d2db-5ee8-9bf6-80791eb21dda"}, {"name": "王晖（947年代州刺史）", "aliases": ["王暉（947年代州刺史）"], "era": "五代十国", "birth_year": null, "death_year": 947, "description": "947年代州刺史，归附契丹后，被史弘肇攻破城池并杀死。不与此前前陵州刺史等同名人物自动合并，生年未载。", "biography": null, "status": "draft", "id": "a73a5ae0-0c3c-5e64-8684-15af38d9d395"}, {"name": "刘在明", "aliases": ["劉在明"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘在明，原戍易州将领。", "biography": null, "status": "draft", "id": "cb5c0d5f-5cf3-50c5-9e63-1b219aa861b0"}, {"name": "骆从朗", "aliases": ["駱從朗"], "era": "五代十国", "birth_year": null, "death_year": 947, "description": "晋州节度副使。947年刘在明去朝契丹时，负责州务，囚禁刘知远派来的张晏洪等使者，随后被药可俦杀死。生年未载。", "biography": null, "status": "draft", "id": "aef348c9-bbbb-5e63-8210-73620c8e39ba"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "张晏洪", "aliases": ["張晏洪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年受刘知远命令出使晋州，宣告即位，被骆从朗囚禁。药可俦杀骆从朗后，推他暂任留后。生卒年未载。", "biography": null, "status": "draft", "id": "a1a8eba0-719f-5faa-b0b9-53ff573f7226"}, {"name": "药可俦", "aliases": ["藥可儔"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋州大将。947年杀死骆从朗，推张晏洪暂任留后；具体日未载，庚辰是派使报告的日期。生卒年未载。", "biography": null, "status": "draft", "id": "fdef428e-5e6d-5e7f-9201-9b10f1d357fc"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "赵熙", "aliases": ["趙熙"], "era": "五代十国", "birth_year": null, "death_year": 947, "description": "右谏议大夫。947年受契丹派遣到晋州征钱帛，催征急迫，骆从朗死后被州民杀死。具体日与生年未载。", "biography": null, "status": "draft", "id": "ba223783-4745-5399-90bb-60320621f246"}, {"name": "赵晖（后汉将领）", "aliases": ["趙暉（後漢將領）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "澶州人，947年二月在陕州与王晏、侯章谋划反抗契丹，刘愿被杀后获推为留后。与887年被部下杀死的上元赵晖不是同一人。生卒年暂未录入。", "biography": null, "status": "draft", "id": "ed9f97dd-d560-5635-bf04-6575c39075b8"}, {"name": "赵矩", "aliases": ["趙矩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "河间人，陕州支使。947年受赵晖派遣，到晋阳向刘知远上表，并劝刘知远早日率兵南下。生卒年未载。", "biography": null, "status": "draft", "id": "d964aacc-a1ec-5d8c-9627-bc055f84659b"}, {"name": "高谟翰", "aliases": ["高謨翰", "高模翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：高谟翰，契丹前锋将领。", "biography": null, "status": "draft", "id": "70516658-fa9a-5bd1-8a0a-55b9844d4772"}, {"name": "侯章", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，947年二月任都头，在陕州与王晏、赵晖共同谋划反抗契丹。生卒年暂未录入。", "biography": null, "status": "draft", "id": "aafc9da4-682f-5473-bedf-46c919bc77c8"}, {"name": "王晏", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐州人，947年二月任奉国都头，与赵晖、侯章谋划杀死契丹将刘愿，率数名壮士夜入府署、取库中兵器。生卒年暂未录入。", "biography": null, "status": "draft", "id": "030a26f1-62e3-5876-92b4-923b763723f0"}, {"name": "高防", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "昭义节度判官。947年张从恩拟往契丹朝见时，他以晋室亲属应守臣节为由劝谏，未被听从；张离镇后留下他协助赵行迁、王守恩。生卒年未载。", "biography": null, "status": "draft", "id": "603ffd47-a5a9-5c5a-90e1-fdc9ea0bc620"}, {"name": "王守恩", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王建立的儿子，与张从恩是姻亲。947年在上党，以左骁卫大将军身份被张从恩暂派为巡检使，协助赵行迁。姻亲具体双方未明，不补具体婚配，生卒年未载。", "biography": null, "status": "draft", "id": "72fe9a16-4716-54d0-bc82-5e7feadc013e"}, {"name": "李万超", "aliases": ["李萬超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋军出身的指挥使。947年驻潞州时，率众入府杀死契丹委任的赵行迁，推王守恩为主帅。《宋史》李万超传补证这一行动。生卒年暂未录入。", "biography": null, "status": "draft", "id": "7b5e692a-1d2f-5684-b29b-59f01d14f44d"}, {"name": "赵行迁", "aliases": ["趙行遷"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "昭义节度副使。947年张从恩赴契丹朝见前，让他主持留后事务，并由王守恩、高防协助。生卒年未载。", "biography": null, "status": "draft", "id": "dd85b151-1c01-5e90-9855-53b893b0053a"}, {"name": "郎五", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年正月耶律德光任命他为镇宁节度使。《资治通鉴》称其为族人，具体亲等未说明，不建立具体血缘关系；生卒年未载。", "biography": null, "status": "draft", "id": "e3f58742-cf58-5340-8710-12036d6edab3"}, {"name": "王琼（947年澶州首领）", "aliases": ["王瓊（947年澶州首領）"], "era": "五代十国", "birth_year": null, "death_year": 947, "description": "947年澶州武装首领，率一千余人攻取南城，围困契丹节度使，后向刘知远求救。最终兵败被杀，具体死亡日各书记述范围不同。与其他同名官员暂不合并，生年未载。", "biography": null, "status": "draft", "id": "f8e33fa7-04c1-5546-8ee3-2e3d8dc49f4e"}, {"name": "张乙（夏津首领）", "aliases": ["張乙（夏津首領）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "夏津武装首领。《旧五代史》记947年与澶州水运什长王琼联络，聚集千余人反抗契丹。生卒年未载。", "biography": null, "status": "draft", "id": "618f891c-9a86-5a12-9645-9a2bdec37603"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "王超（王琼弟）", "aliases": ["王超（王瓊弟）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年澶州首领王琼的弟弟，被派往刘知远处求救。二月癸未得到赏赐后被遣回。与晚唐邠岐判官王超区分，生卒年未载。", "biography": null, "status": "draft", "id": "71f53334-c01f-58ee-8fa8-3cc88fab3be1"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
